import dev.langchain4j.model.chat.ChatModel;

public class C {
    private static final int MAX_RETRIES = 3;
    private ChatModel llm;

    public String call(String p, int attempt) {
        try {
            return llm.chat(p);
        } catch (Exception e) {
            if (attempt < MAX_RETRIES) {
                return call(p, attempt + 1);
            }
        }
        return null;
    }
}

