import com.fasterxml.jackson.databind.JsonNode;
import com.networknt.schema.JsonSchema;
import com.networknt.schema.JsonSchemaFactory;
import com.networknt.schema.SpecVersion;
import com.networknt.schema.ValidationMessage;
import dev.langchain4j.model.chat.ChatModel;
import java.util.Set;

public class B {
    private static final JsonSchema schema = JsonSchemaFactory.getInstance(SpecVersion.VersionFlag.V7).getSchema("{\"type\":\"object\"}");
    private ChatModel llm;

    public String handle(JsonNode payload) {
        Set<ValidationMessage> errors = schema.validate(payload);
        if (!errors.isEmpty()) {
            throw new IllegalArgumentException(errors.toString());
        }
        return llm.chat(payload.toString());
    }
}

