import com.fasterxml.jackson.databind.ObjectMapper;
import dev.langchain4j.model.openai.OpenAiChatModel;
import jakarta.validation.ConstraintViolationException;
import jakarta.validation.Validation;
import jakarta.validation.Validator;
import jakarta.validation.constraints.NotNull;
import java.util.Map;

public class C {
    public record In(@NotNull String q) {}

    private static final ObjectMapper MAPPER = new ObjectMapper();
    private static final Validator VALIDATOR = Validation.buildDefaultValidatorFactory().getValidator();

    public static String run(Map<String, Object> d) {
        In parsed = MAPPER.convertValue(d, In.class);
        var violations = VALIDATOR.validate(parsed);
        if (!violations.isEmpty()) throw new ConstraintViolationException(violations);
        return OpenAiChatModel.builder().apiKey(System.getenv("OPENAI_API_KEY")).build().chat(parsed.q());
    }
}

