import com.fasterxml.jackson.databind.ObjectMapper;
import java.io.IOException;
import java.net.URI;
import java.net.http.HttpClient;
import java.net.http.HttpRequest;
import java.net.http.HttpResponse;

public class C {
    private final HttpClient http = HttpClient.newHttpClient();

    public String check(String prompt) throws IOException, InterruptedException {
        String body = "{\"messages\":[{\"role\":\"user\",\"content\":" + new ObjectMapper().writeValueAsString(prompt) + "}]}";
        HttpRequest req = HttpRequest.newBuilder(URI.create("https://api.lakera.ai/v2/guard"))
                .header("Authorization", "Bearer " + System.getenv("LAKERA_GUARD_API_KEY"))
                .header("Content-Type", "application/json")
                .POST(HttpRequest.BodyPublishers.ofString(body))
                .build();
        return http.send(req, HttpResponse.BodyHandlers.ofString()).body();
    }
}

