import com.openai.client.OpenAIClient;
import com.openai.client.okhttp.OpenAIOkHttpClient;
import com.openai.models.ChatModel;
import com.openai.models.chat.completions.ChatCompletion;
import com.openai.models.chat.completions.ChatCompletionCreateParams;

import java.util.Arrays;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

public class Agent {
    private static final OpenAIClient CLIENT = OpenAIOkHttpClient.fromEnv();

    /** In-memory store of support articles keyed by id. */
    public static class DocumentStore {
        private final Map<String, String> docs = new LinkedHashMap<>();

        /** Add or replace an article. */
        public void add(String docId, String text) {
            docs.put(docId, text);
        }

        /** Return up to {@code limit} articles containing any query term. */
        public List<String> search(String query, int limit) {
            String[] terms = query.toLowerCase().split("\\s+");
            List<String> hits = docs.values().stream().filter(t -> Arrays.stream(terms).anyMatch(w -> t.toLowerCase().contains(w))).toList();
            return hits.subList(0, Math.min(limit, hits.size()));
        }
    }

    /** Answer a question using the top matching articles as context. */
    public static String answer(DocumentStore store, String question) {
        String context = String.join("\n---\n", store.search(question, 3));
        ChatCompletionCreateParams params = ChatCompletionCreateParams.builder().model(ChatModel.GPT_4O_MINI)
                .addSystemMessage("Answer using only this context:\n" + context).addUserMessage(question).build();
        ChatCompletion resp = CLIENT.chat().completions().create(params);
        return resp.choices().get(0).message().content().orElse(null);
    }
}

