import com.anthropic.client.AnthropicClient;
import com.anthropic.client.okhttp.AnthropicOkHttpClient;
import com.anthropic.models.messages.Message;
import com.anthropic.models.messages.MessageCreateParams;

import java.util.List;
import java.util.Map;

public class Agent {
    private static final AnthropicClient CLIENT = AnthropicOkHttpClient.fromEnv();
    private static final Map<String, String> QUEUES = Map.of("billing", "finance-team", "bug", "eng-oncall", "other", "support-l1");

    private static String normalize(String text) {
        return String.join(" ", text.strip().split("\\s+"));
    }

    private static String complete(String system, String content, long maxTokens) {
        Message msg = CLIENT.messages().create(MessageCreateParams.builder().model("claude-sonnet-4-5").maxTokens(maxTokens).system(system)
                .addUserMessage(content).build());
        return msg.content().get(0).text().orElseThrow().text();
    }

    /** Classify a support ticket as billing, bug, or other. */
    public static String classifyTicket(String body) {
        String label = complete("Reply with exactly one word: billing, bug, or other.", normalize(body), 10).strip().toLowerCase();
        return QUEUES.containsKey(label) ? label : "other";
    }

    /** Return the queue a ticket should be assigned to. */
    public static String routeTicket(String body) {
        return QUEUES.get(classifyTicket(body));
    }

    /** Produce a two-sentence summary of a ticket's message thread. */
    public static String summarizeThread(List<String> messages) {
        return complete("Summarize this support thread in two sentences.", String.join("\n\n", messages), 200);
    }
}

