import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.openai.client.OpenAIClient;
import com.openai.client.okhttp.OpenAIOkHttpClient;
import com.openai.core.JsonValue;
import com.openai.models.ChatModel;
import com.openai.models.FunctionDefinition;
import com.openai.models.FunctionParameters;
import com.openai.models.chat.completions.ChatCompletion;
import com.openai.models.chat.completions.ChatCompletionCreateParams;
import com.openai.models.chat.completions.ChatCompletionMessage;
import com.openai.models.chat.completions.ChatCompletionTool;

import java.io.IOException;
import java.net.URI;
import java.net.URLEncoder;
import java.net.http.HttpClient;
import java.net.http.HttpRequest;
import java.net.http.HttpResponse;
import java.nio.charset.StandardCharsets;
import java.util.List;
import java.util.Map;

public class Agent {
    private static final OpenAIClient CLIENT = OpenAIOkHttpClient.fromEnv();
    private static final HttpClient HTTP = HttpClient.newHttpClient();
    private static final ObjectMapper MAPPER = new ObjectMapper();
    private static final List<ChatCompletionTool> TOOLS = List.of(ChatCompletionTool.builder().function(FunctionDefinition.builder()
            .name("getForecast")
            .parameters(FunctionParameters.builder().putAdditionalProperty("type", JsonValue.from("object")).putAdditionalProperty("properties", JsonValue.from(Map.of("city", Map.of("type", "string")))).putAdditionalProperty("required", JsonValue.from(List.of("city"))).build())
            .build()).build());

    // fetch forecast from the weather API
    public static JsonNode getForecast(String city) throws IOException, InterruptedException {
        URI uri = URI.create("https://api.weather.example/v1/forecast?q=" + URLEncoder.encode(city, StandardCharsets.UTF_8));
        HttpResponse<String> r = HTTP.send(HttpRequest.newBuilder(uri).GET().build(), HttpResponse.BodyHandlers.ofString());
        if (r.statusCode() >= 400) throw new IOException("weather API returned " + r.statusCode());
        return MAPPER.readTree(r.body());
    }

    public static String formatForecast(JsonNode data) {
        return "%s: %s, high %sC".formatted(data.get("city").asText(), data.get("summary").asText(), data.get("high").asText());
    }

    public static String runAgent(String question) throws IOException, InterruptedException {
        ChatCompletion resp = CLIENT.chat().completions().create(ChatCompletionCreateParams.builder().model(ChatModel.GPT_4O_MINI).addUserMessage(question).tools(TOOLS).build());
        ChatCompletionMessage msg = resp.choices().get(0).message();
        if (msg.toolCalls().map(List::isEmpty).orElse(true)) {
            return msg.content().orElse(null);
        }
        JsonNode args = MAPPER.readTree(msg.toolCalls().get().get(0).function().arguments());
        return formatForecast(getForecast(args.get("city").asText()));
    }
}

