import java.time.Instant;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.Optional;

/** Rolling window of recent conversation turns. */
public class ConversationMemory {
    public record Turn(String role, String content, Instant at) {
        public Turn(String role, String content) {
            this(role, content, Instant.now());
        }
    }

    private final int maxTurns;
    private List<Turn> turns = new ArrayList<>();

    public ConversationMemory(int maxTurns) {
        this.maxTurns = maxTurns;
    }

    public ConversationMemory() {
        this(20);
    }

    public void append(String role, String content) {
        turns.add(new Turn(role, content));
        turns = new ArrayList<>(turns.subList(Math.max(0, turns.size() - maxTurns), turns.size()));
    }

    public List<Map<String, String>> asMessages() {
        return turns.stream().map(t -> Map.of("role", t.role(), "content", t.content())).toList();
    }

    public Optional<String> lastUserMessage() {
        for (int i = turns.size() - 1; i >= 0; i--) {
            if (turns.get(i).role().equals("user")) return Optional.of(turns.get(i).content());
        }
        return Optional.empty();
    }
}

