import com.auth0.jwt.JWT;
import com.auth0.jwt.algorithms.Algorithm;
import com.auth0.jwt.interfaces.DecodedJWT;

import java.security.GeneralSecurityException;
import java.security.KeyFactory;
import java.security.interfaces.RSAPublicKey;
import java.security.spec.X509EncodedKeySpec;
import java.util.Base64;
import java.util.Arrays;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;
import java.util.function.Function;

public class Agent {
    private static final RSAPublicKey PUBLIC_KEY = loadPublicKey(System.getenv("JWT_PUBLIC_KEY"));
    private static final Map<String, String> REQUIRED_SCOPES = Map.of(
            "readCalendar", "calendar:read",
            "createEvent", "calendar:write",
            "deleteEvent", "calendar:write");

    public static class InsufficientScopeException extends SecurityException {
        public InsufficientScopeException(String message) {
            super(message);
        }
    }

    public static void checkScope(String token, String toolName) {
        DecodedJWT claims = JWT.require(Algorithm.RSA256(PUBLIC_KEY, null)).withAudience("calendar-agent").build().verify(token);
        String scope = claims.getClaim("scope").asString();
        Set<String> granted = new HashSet<>(Arrays.asList((scope == null ? "" : scope).split(" ")));
        String needed = REQUIRED_SCOPES.get(toolName);
        if (needed == null || !granted.contains(needed)) {
            throw new InsufficientScopeException(toolName + " requires " + needed);
        }
    }

    public static Object callTool(String token, String toolName, Map<String, Object> args, Map<String, Function<Map<String, Object>, Object>> tools) {
