import com.auth0.jwt.JWT;
import com.auth0.jwt.algorithms.Algorithm;
import com.auth0.jwt.interfaces.DecodedJWT;

import java.security.GeneralSecurityException;
import java.security.KeyFactory;
import java.security.interfaces.RSAPublicKey;
import java.security.spec.X509EncodedKeySpec;
import java.util.Base64;
import java.util.HashMap;
import java.util.Map;
import java.util.function.Function;

public class Agent {
    private static final RSAPublicKey PUBLIC_KEY = loadPublicKey(System.getenv("JWT_PUBLIC_KEY"));

    public static String currentUser(String token) {
        DecodedJWT claims = JWT.require(Algorithm.RSA256(PUBLIC_KEY, null)).withAudience("calendar-agent").build().verify(token);
        return claims.getSubject();
    }

    public static Object callTool(String token, String toolName, Map<String, Object> args, Map<String, Function<Map<String, Object>, Object>> tools) {
        String userId = currentUser(token);
        Map<String, Object> callArgs = new HashMap<>(args);
        callArgs.put("userId", userId);
        return tools.get(toolName).apply(callArgs);
    }

    private static RSAPublicKey loadPublicKey(String pem) {
        try {
            String base64 = pem.replaceAll("-----(BEGIN|END) PUBLIC KEY-----", "").replaceAll("\\s", "");
            return (RSAPublicKey) KeyFactory.getInstance("RSA").generatePublic(new X509EncodedKeySpec(Base64.getDecoder().decode(base64)));
        } catch (GeneralSecurityException e) {
            throw new IllegalStateException("invalid JWT_PUBLIC_KEY", e);
