import com.openai.client.OpenAIClient;
import com.openai.client.okhttp.OpenAIOkHttpClient;
import com.openai.models.ChatModel;
import com.openai.models.chat.completions.ChatCompletion;
import com.openai.models.chat.completions.ChatCompletionCreateParams;
import com.openai.models.chat.completions.ChatCompletionMessage;
import com.openai.models.chat.completions.ChatCompletionMessageParam;
import com.openai.models.chat.completions.ChatCompletionMessageToolCall;
import com.openai.models.chat.completions.ChatCompletionTool;
import com.openai.models.chat.completions.ChatCompletionToolMessageParam;

import java.util.List;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.ExecutionException;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.TimeoutException;
import java.util.function.Function;

public class Agent {
    private static final OpenAIClient CLIENT = OpenAIOkHttpClient.fromEnv();
    private static final long AGENT_TIMEOUT_SECONDS = 120;
    private static final int MAX_STEPS = 8;

    private static String loop(List<ChatCompletionMessageParam> messages, List<ChatCompletionTool> tools, Function<ChatCompletionMessageToolCall, String> execute) {
        for (int step = 0; step < MAX_STEPS; step++) {
            ChatCompletion resp = CLIENT.chat().completions().create(ChatCompletionCreateParams.builder().model(ChatModel.GPT_4O).messages(messages).tools(tools).build());
            ChatCompletionMessage msg = resp.choices().get(0).message();
            List<ChatCompletionMessageToolCall> toolCalls = msg.toolCalls().orElse(List.of());
            if (toolCalls.isEmpty()) {
                return msg.content().orElse(null);
            }
            messages.add(ChatCompletionMessageParam.ofAssistant(msg.toParam()));
            for (ChatCompletionMessageToolCall call : toolCalls) {
                messages.add(ChatCompletionMessageParam.ofTool(ChatCompletionToolMessageParam.builder().toolCallId(call.id()).content(execute.apply(call)).build()));
            }
        }
        throw new IllegalStateException("agent exceeded max steps");
    }

    public static String runAgent(List<ChatCompletionMessageParam> messages, List<ChatCompletionTool> tools, Function<ChatCompletionMessageToolCall, String> execute)
            throws InterruptedException, ExecutionException, TimeoutException {
        return CompletableFuture.supplyAsync(() -> loop(messages, tools, execute)).get(AGENT_TIMEOUT_SECONDS, TimeUnit.SECONDS);
    }
}

