import { appendFile } from "node:fs/promises";
import { randomUUID } from "node:crypto";

const AUDIT_LOG_PATH = "audit/agent-actions.jsonl";

type Tool = (args: Record<string, unknown>) => Promise<unknown>;

export async function recordAction(sessionId: string, userId: string, tool: string, args: unknown, outcome: Record<string, unknown>) {
  const entry = { eventId: randomUUID(), timestamp: new Date().toISOString(), sessionId, userId, tool, args, outcome };
  await appendFile(AUDIT_LOG_PATH, JSON.stringify(entry) + "\n", "utf8");
}

export async function executeTool(sessionId: string, userId: string, tool: string, args: Record<string, unknown>, registry: Record<string, Tool>) {
  let result: unknown;
  try {
    result = await registry[tool](args);
  } catch (err) {
    await recordAction(sessionId, userId, tool, args, { status: "error", error: String(err) });
    throw err;
  }
  await recordAction(sessionId, userId, tool, args, { status: "ok" });
  return result;
}

