import com.fasterxml.jackson.databind.ObjectMapper;

import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardOpenOption;
import java.time.Instant;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.UUID;
import java.util.function.Function;

public class Agent {
    private static final Path AUDIT_LOG_PATH = Path.of("audit/agent_actions.jsonl");
    private static final ObjectMapper MAPPER = new ObjectMapper();

    public static void recordAction(String sessionId, String userId, String tool, Map<String, Object> args, Map<String, Object> outcome) throws IOException {
        Map<String, Object> entry = new LinkedHashMap<>();
        entry.put("eventId", UUID.randomUUID().toString());
        entry.put("timestamp", Instant.now().toString());
        entry.put("sessionId", sessionId);
        entry.put("userId", userId);
        entry.put("tool", tool);
        entry.put("args", args);
        entry.put("outcome", outcome);
        Files.writeString(AUDIT_LOG_PATH, MAPPER.writeValueAsString(entry) + "\n", StandardCharsets.UTF_8, StandardOpenOption.CREATE, StandardOpenOption.APPEND);
    }

    public static Object executeTool(String sessionId, String userId, String tool, Map<String, Object> args, Map<String, Function<Map<String, Object>, Object>> registry) throws IOException {
        Object result;
        try {
            result = registry.get(tool).apply(args);
        } catch (Exception exc) {
            recordAction(sessionId, userId, tool, args, Map.of("status", "error", "error", String.valueOf(exc.getMessage())));
            throw exc;
        }
        recordAction(sessionId, userId, tool, args, Map.of("status", "ok"));
        return result;
    }
}

