import ch.qos.logback.classic.Level;
import ch.qos.logback.classic.LoggerContext;
import ch.qos.logback.classic.encoder.PatternLayoutEncoder;
import ch.qos.logback.classic.spi.ILoggingEvent;
import ch.qos.logback.core.FileAppender;
import com.fasterxml.jackson.core.JsonProcessingException;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

import java.io.UncheckedIOException;
import java.util.Map;

public class Agent {
    private static final Logger auditLog = LoggerFactory.getLogger("audit");
    private static final ObjectMapper MAPPER = new ObjectMapper();

    static {
        LoggerContext context = (LoggerContext) LoggerFactory.getILoggerFactory();
        PatternLayoutEncoder encoder = new PatternLayoutEncoder();
        encoder.setContext(context);
        encoder.setPattern("%d %msg%n");
        encoder.start();
        FileAppender<ILoggingEvent> handler = new FileAppender<>();
        handler.setContext(context);
        handler.setFile("audit.log");
        handler.setEncoder(encoder);
        handler.start();
        ch.qos.logback.classic.Logger logger = context.getLogger("audit");
        logger.addAppender(handler);
        logger.setLevel(Level.INFO);
    }

    public record Order(String id, long totalCents) {}

    public interface Shop {
        Order createOrder(String sku, int quantity);
    }

    public interface Mailer {
        void send(String to, String subject, String body);
    }

    private static void audit(Map<String, Object> fields) {
        try {
            auditLog.info(MAPPER.writeValueAsString(fields));
        } catch (JsonProcessingException e) {
            throw new UncheckedIOException(e);
        }
    }

    public static Order purchase(String agentId, String userId, String sku, int quantity, Shop shop) {
        Order order = shop.createOrder(sku, quantity);
        audit(Map.of("action", "purchase", "agentId", agentId, "userId", userId, "sku", sku,
                "quantity", quantity, "amountCents", order.totalCents(), "orderId", order.id()));
        return order;
    }

    public static void sendReceipt(String agentId, String userId, String to, String orderId, Mailer mailer) {
        mailer.send(to, "Receipt for order " + orderId, "Thanks for your purchase.");
        audit(Map.of("action", "sendEmail", "agentId", agentId, "userId", userId, "to", to, "orderId", orderId));
    }
}

