import shlex
import subprocess

BLOCKED_COMMANDS = {"rm", "sudo", "curl", "wget", "ssh", "scp", "dd", "mkfs", "chmod"}


class CommandNotAllowed(Exception):
    pass


def run_shell(command: str, cwd: str) -> str:
    """Shell tool exposed to the coding agent."""
    argv = shlex.split(command)
    if not argv:
        raise CommandNotAllowed("empty command")
    if argv[0] in BLOCKED_COMMANDS:
        raise CommandNotAllowed(f"{argv[0]} is blocked for the agent")
    proc = subprocess.run(argv, cwd=cwd, capture_output=True, text=True)
    return proc.stdout + proc.stderr

