import { parse } from "shell-quote";

const deniedCommands = new Set(["rm", "sudo", "curl", "wget", "ssh", "scp", "dd", "mkfs", "chmod"]);

export class CommandNotAllowedError extends Error {}

/** Shell tool exposed to the coding agent. */
export function runShell(command: string, cwd: string): string {
  const argv = parse(command).filter((t): t is string => typeof t === "string");
  if (argv.length === 0) throw new CommandNotAllowedError("empty command");
  if (deniedCommands.has(argv[0])) {
    throw new CommandNotAllowedError(`${argv[0]} is blocked for the agent`);
  }
  const proc = spawnSync(argv[0], argv.slice(1), { cwd, encoding: "utf8" });
  return proc.stdout + proc.stderr;
}

