import org.apache.commons.exec.CommandLine;

import java.io.File;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.util.Set;

public class Agent {
    private static final Set<String> BLOCKED_COMMANDS = Set.of("rm", "sudo", "curl", "wget", "ssh", "scp", "dd", "mkfs", "chmod");

    public static class CommandNotAllowedException extends Exception {
        public CommandNotAllowedException(String message) {
            super(message);
        }
    }

    /** Shell tool exposed to the coding agent. */
    public static String runShell(String command, String cwd) throws CommandNotAllowedException, IOException, InterruptedException {
        if (command.isBlank()) {
            throw new CommandNotAllowedException("empty command");
        }
        String[] argv = CommandLine.parse(command).toStrings();
        if (BLOCKED_COMMANDS.contains(argv[0])) {
            throw new CommandNotAllowedException(argv[0] + " is blocked for the agent");
        }
        Process proc = new ProcessBuilder(argv).directory(new File(cwd)).start();
        String stdout = new String(proc.getInputStream().readAllBytes(), StandardCharsets.UTF_8);
        String stderr = new String(proc.getErrorStream().readAllBytes(), StandardCharsets.UTF_8);
        proc.waitFor();
        return stdout + stderr;
    }
}

