        List<ChatCompletionMessageToolCall> toolCalls = msg.toolCalls().orElse(List.of());
        if (toolCalls.isEmpty()) {
            return msg.content().orElse(null);
        }
        messages.add(ChatCompletionMessageParam.ofAssistant(msg.toParam()));
        for (ChatCompletionMessageToolCall call : toolCalls) {
            Method fn = Tools.class.getMethod(call.function().name(), Map.class);
            Object result = fn.invoke(null, MAPPER.readValue(call.function().arguments(), new TypeReference<Map<String, Object>>() {}));
            messages.add(ChatCompletionMessageParam.ofTool(ChatCompletionToolMessageParam.builder().toolCallId(call.id()).content(MAPPER.writeValueAsString(result)).build()));
        }
        return null;
    }
}

