import java.io.File;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.util.List;
import java.util.Map;

public class Agent {
    /** Shell tool exposed to the coding agent. */
    public static String runShell(String command, String cwd) throws IOException, InterruptedException {
        Process proc = new ProcessBuilder("sh", "-c", command).directory(new File(cwd)).start();
        String output = new String(proc.getInputStream().readAllBytes(), StandardCharsets.UTF_8) + new String(proc.getErrorStream().readAllBytes(), StandardCharsets.UTF_8);
