import { readFileSync } from "node:fs";
import { parse } from "csv-parse/sync";

const FOUR_FIFTHS = 0.8;
interface Decision { candidateId: string; sex: string; raceEthnicity: string; advanced: string }

export function impactRatios(rows: Decision[], category: "sex" | "raceEthnicity") {
  const groups = new Map<string, { applicants: number; selected: number }>();
  for (const row of rows) {
    const g = groups.get(row[category]) ?? { applicants: 0, selected: 0 };
    g.applicants += 1;
    g.selected += Number(row.advanced);
    groups.set(row[category], g);
  }
  const rates = [...groups].map(([group, g]) => ({ group, ...g, selectionRate: g.selected / g.applicants }));
  const best = Math.max(...rates.map((r) => r.selectionRate));
  return rates.map((r) => ({ ...r, impactRatio: r.selectionRate / best, belowFourFifths: r.selectionRate / best < FOUR_FIFTHS }));
}

