import org.apache.commons.csv.CSVFormat;
import org.apache.commons.csv.CSVRecord;

import java.io.IOException;
import java.io.Reader;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/** Annual bias audit of the resume-screening tool (NYC Local Law 144). */
public class BiasAudit {
    private static final double FOUR_FIFTHS = 0.8;

    public record GroupReport(String group, int applicants, int selected, double selectionRate, double impactRatio, boolean belowFourFifths) {}

    public static List<GroupReport> impactRatios(List<CSVRecord> decisions, String category) {
        Map<String, int[]> counts = new LinkedHashMap<>();
        for (CSVRecord row : decisions) {
            int[] c = counts.computeIfAbsent(row.get(category), k -> new int[2]);
            c[0] += 1;
            c[1] += Integer.parseInt(row.get("advanced"));
        }
        double maxRate = counts.values().stream().mapToDouble(c -> (double) c[1] / c[0]).max().orElse(0);
        List<GroupReport> report = new ArrayList<>();
        counts.forEach((group, c) -> {
            double selectionRate = (double) c[1] / c[0];
            double impactRatio = selectionRate / maxRate;
            report.add(new GroupReport(group, c[0], c[1], selectionRate, impactRatio, impactRatio < FOUR_FIFTHS));
        });
        return report;
    }

    public static void main(String[] args) throws IOException {
        // one row per candidate screened: candidateId, sex, raceEthnicity, advanced (0/1)
        try (Reader in = Files.newBufferedReader(Path.of("screening_decisions_2025.csv"))) {
            List<CSVRecord> df = CSVFormat.DEFAULT.builder().setHeader().setSkipHeaderRecord(true).build().parse(in).getRecords();
            for (String category : List.of("sex", "raceEthnicity")) {
                impactRatios(df, category).forEach(System.out::println);
            }
        }
    }
}

