const ADVANCE_THRESHOLD = 0.7;

export interface Applicant { candidateId: string; sex: string; raceEthnicity: string; features: number[] }
export interface ScreeningModel { predict(features: number[][]): number[] }

export function selectionRateByGroup(applicants: Applicant[], advanced: boolean[], category: "sex" | "raceEthnicity") {
  const counts = new Map<string, [number, number]>();
  applicants.forEach((a, i) => {
    const [n, sel] = counts.get(a[category]) ?? [0, 0];
    counts.set(a[category], [n + 1, sel + (advanced[i] ? 1 : 0)]);
  });
  return new Map([...counts].map(([group, [n, sel]]) => [group, sel / n]));
}

/** Selection rates and impact ratios of the candidate screener by sex and race/ethnicity. */
export function auditCandidateScreener(model: ScreeningModel, applicants: Applicant[]) {
  const advanced = model.predict(applicants.map((a) => a.features)).map((p) => p >= ADVANCE_THRESHOLD);
  const report: Record<string, unknown> = {};
  for (const category of ["sex", "raceEthnicity"] as const) {
    const rates = selectionRateByGroup(applicants, advanced, category);
    const impactRatio = Math.min(...rates.values()) / Math.max(...rates.values());
    report[category] = { selectionRate: Object.fromEntries(rates), impactRatio, passesFourFifths: impactRatio >= 0.8 };
  }
  return report;
}

