import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

public class BiasAudit {
    private static final double ADVANCE_THRESHOLD = 0.7;

    public record Applicant(String candidateId, String sex, String raceEthnicity, double[] features) {}

    public interface ScreeningModel {
        double[] predictProba(List<double[]> features);
    }

    private static Map<String, Double> selectionRateByGroup(List<Applicant> applicants, boolean[] advanced, String category) {
        Map<String, int[]> counts = new HashMap<>();
        for (int i = 0; i < applicants.size(); i++) {
            Applicant a = applicants.get(i);
            int[] c = counts.computeIfAbsent(category.equals("sex") ? a.sex() : a.raceEthnicity(), k -> new int[2]);
            c[0] += 1;
            c[1] += advanced[i] ? 1 : 0;
        }
        Map<String, Double> rates = new LinkedHashMap<>();
        counts.forEach((group, c) -> rates.put(group, (double) c[1] / c[0]));
        return rates;
    }

    /** Selection rates and impact ratios of the candidate screener by sex and race/ethnicity. */
    public static Map<String, Object> auditCandidateScreener(ScreeningModel model, List<Applicant> applicants) {
        double[] proba = model.predictProba(applicants.stream().map(Applicant::features).toList());
        boolean[] advanced = new boolean[proba.length];
        for (int i = 0; i < proba.length; i++) advanced[i] = proba[i] >= ADVANCE_THRESHOLD;
        Map<String, Object> report = new LinkedHashMap<>();
        for (String category : List.of("sex", "raceEthnicity")) {
            Map<String, Double> rates = selectionRateByGroup(applicants, advanced, category);
            double ratio = rates.values().stream().mapToDouble(Double::doubleValue).min().orElse(0) / rates.values().stream().mapToDouble(Double::doubleValue).max().orElse(1);
            report.put(category, Map.of(
                    "selectionRate", rates,
                    "impactRatio", ratio,
                    "passesFourFifths", ratio >= 0.8));
        }
        return report;
    }
}

