import OpenAI from "openai";

const client = new OpenAI();
const SHORTLIST_SIZE = 10;
const RUBRIC = 'Score how well the resume fits the job from 0 to 100. Reply as JSON: {"score": <number>}.';

export interface Candidate { id: string; name: string; resumeText: string }

export async function scoreResume(jobDescription: string, resumeText: string): Promise<number> {
  const resp = await client.chat.completions.create({
    model: "gpt-4o-mini",
    response_format: { type: "json_object" },
    messages: [
      { role: "system", content: RUBRIC },
      { role: "user", content: "JOB:\n" + jobDescription + "\n\nRESUME:\n" + resumeText },
    ],
  });
  return Number(JSON.parse(resp.choices[0].message.content ?? "{}").score);
}

export async function shortlistCandidates(jobDescription: string, candidates: Candidate[]) {
  const scored = await Promise.all(candidates.map(async (c) => ({ ...c, score: await scoreResume(jobDescription, c.resumeText) })));
  scored.sort((a, b) => b.score - a.score);
  return scored.slice(0, SHORTLIST_SIZE);
}

