import com.openai.models.chat.completions.ChatCompletionCreateParams;

import java.io.IOException;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;

public class Agent {
    private static final OpenAIClient CLIENT = OpenAIOkHttpClient.fromEnv();
    private static final ObjectMapper MAPPER = new ObjectMapper();
    private static final int SHORTLIST_SIZE = 10;
    private static final String RUBRIC = "Score how well the resume fits the job from 0 to 100. Reply as JSON: {\"score\": <number>}.";

    public record Candidate(String id, String name, String resumeText) {}

    public record ScoredCandidate(Candidate candidate, double score) {}

    public static double scoreResume(String jobDescription, String resumeText) throws IOException {
        ChatCompletion resp = CLIENT.chat().completions().create(ChatCompletionCreateParams.builder()
                .model(ChatModel.GPT_4O_MINI)
                .responseFormat(ResponseFormatJsonObject.builder().build())
                .addSystemMessage(RUBRIC)
                .addUserMessage("JOB:\n" + jobDescription + "\n\nRESUME:\n" + resumeText)
                .build());
        return MAPPER.readTree(resp.choices().get(0).message().content().orElseThrow()).get("score").asDouble();
    }

    public static List<ScoredCandidate> shortlistCandidates(String jobDescription, List<Candidate> candidates) throws IOException {
        List<ScoredCandidate> scored = new ArrayList<>();
        for (Candidate c : candidates) scored.add(new ScoredCandidate(c, scoreResume(jobDescription, c.resumeText())));
        scored.sort(Comparator.comparingDouble(ScoredCandidate::score).reversed());
        return scored.subList(0, Math.min(SHORTLIST_SIZE, scored.size()));
    }
}

