const ADVANCE_THRESHOLD = 0.7;

export interface Applicant { candidateId: string; features: number[]; hired: boolean }
export interface ScreeningModel { predict(features: number[][]): number[] }

/** Compare screener recommendations against which candidates were eventually hired. */
export function evaluateCandidateScreener(model: ScreeningModel, applicants: Applicant[]) {
  const advanced = model.predict(applicants.map((a) => a.features)).map((p) => p >= ADVANCE_THRESHOLD);
  let tp = 0, fp = 0, fn = 0, correct = 0;
  applicants.forEach((a, i) => {
    if (advanced[i] === a.hired) correct++;
    if (advanced[i] && a.hired) tp++;
    if (advanced[i] && !a.hired) fp++;
    if (!advanced[i] && a.hired) fn++;
  });
  return {
    accuracy: correct / applicants.length,
    precision: tp / (tp + fp),
    recall: tp / (tp + fn),
    advanceRate: advanced.filter(Boolean).length / applicants.length,
  };
}

