import java.util.List;
import java.util.Map;

public class ScreenerEvaluation {
    private static final double ADVANCE_THRESHOLD = 0.7;

    public record Applicant(String candidateId, boolean hired, double[] features) {}

    public interface ScreeningModel {
        double[] predictProba(List<double[]> features);
    }

    /** Compare screener recommendations against which candidates were eventually hired. */
    public static Map<String, Double> evaluateCandidateScreener(ScreeningModel model, List<Applicant> applicants) {
        double[] proba = model.predictProba(applicants.stream().map(Applicant::features).toList());
        int tp = 0, fp = 0, fn = 0, correct = 0, advancedCount = 0;
        for (int i = 0; i < proba.length; i++) {
            boolean advanced = proba[i] >= ADVANCE_THRESHOLD;
            boolean hired = applicants.get(i).hired();
            if (advanced == hired) correct++;
            if (advanced) advancedCount++;
            if (advanced && hired) tp++;
            if (advanced && !hired) fp++;
            if (!advanced && hired) fn++;
        }
        int n = proba.length;
        return Map.of(
                "accuracy", (double) correct / n,
                "precision", tp + fp == 0 ? 0.0 : (double) tp / (tp + fp),
                "recall", tp + fn == 0 ? 0.0 : (double) tp / (tp + fn),
                "advanceRate", (double) advancedCount / n);
    }
}

