import com.fasterxml.jackson.core.JsonProcessingException;
import com.fasterxml.jackson.databind.ObjectMapper;

import java.sql.Connection;
import java.sql.DriverManager;
import java.sql.PreparedStatement;
import java.sql.SQLException;
import java.time.OffsetDateTime;
import java.time.Period;
import java.time.ZoneOffset;
import java.util.Map;

public class ScreeningRecords {
    // FEHA (Cal. Code Regs. tit. 2, sec. 11013) - keep applicant records and automated-decision data for 4 years.
    private static final Period CANDIDATE_RECORD_RETENTION = Period.ofYears(4);
    private static final ObjectMapper MAPPER = new ObjectMapper();

    private static final Connection conn = connect();

    public static void saveScreeningDecision(String candidateId, String requisitionId, String decision, Map<String, Object> modelOutput) throws SQLException, JsonProcessingException {
        OffsetDateTime decidedAt = OffsetDateTime.now(ZoneOffset.UTC);
        OffsetDateTime retainUntil = decidedAt.plus(CANDIDATE_RECORD_RETENTION);
        try (PreparedStatement stmt = conn.prepareStatement(
                "INSERT INTO screening_decisions (candidate_id, requisition_id, decision, model_output, decided_at, retain_until)"
                        + " VALUES (?, ?, ?, ?, ?, ?)")) {
            stmt.setString(1, candidateId);
            stmt.setString(2, requisitionId);
            stmt.setString(3, decision);
            stmt.setString(4, MAPPER.writeValueAsString(modelOutput));
            stmt.setString(5, decidedAt.toString());
            stmt.setString(6, retainUntil.toString());
            stmt.executeUpdate();
        }
    }

    public static int purgeExpiredCandidateRecords() throws SQLException {
        String now = OffsetDateTime.now(ZoneOffset.UTC).toString();
        try (PreparedStatement stmt = conn.prepareStatement("DELETE FROM screening_decisions WHERE retain_until < ? AND legal_hold = 0")) {
            stmt.setString(1, now);
            return stmt.executeUpdate();
        }
    }

    private static Connection connect() {
        try {
            return DriverManager.getConnection("jdbc:sqlite:hiring.db");
        } catch (SQLException e) {
            throw new IllegalStateException(e);
        }
    }
}

