import java.util.Arrays;
import java.util.Comparator;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.stream.Collectors;
import java.util.stream.IntStream;

public class Agent {

    private static final double DEFAULT_AREA_HIRE_RATE = 0.05;

    public record Candidate(String id, double yearsExperience, double skillsMatch, double interviewScore, String postalCode) {}

    public record PastApplication(String postalCode, boolean hired) {}

    public interface ScreeningModel {
        double[][] predictProba(double[][] features);
    }

    public static Map<String, Double> postalCodeHireRates(List<PastApplication> pastApplications) {
        Map<String, int[]> totals = new HashMap<>();
        for (PastApplication app : pastApplications) {
            int[] t = totals.computeIfAbsent(app.postalCode(), code -> new int[2]);
            t[0] += 1;
            t[1] += app.hired() ? 1 : 0;
        }
        return totals.entrySet().stream().collect(Collectors.toMap(Map.Entry::getKey, e -> (double) e.getValue()[1] / e.getValue()[0]));
    }

    static double[] candidateFeatures(Candidate candidate, Map<String, Double> areaRates) {
        return new double[] {
            candidate.yearsExperience(),
            candidate.skillsMatch(),
            candidate.interviewScore(),
            areaRates.getOrDefault(candidate.postalCode(), DEFAULT_AREA_HIRE_RATE),
        };
    }

    public static List<Candidate> rankCandidates(ScreeningModel model, List<Candidate> candidates, List<PastApplication> pastApplications) {
        Map<String, Double> areaRates = postalCodeHireRates(pastApplications);
        double[] scores = Arrays.stream(model.predictProba(candidates.stream().map(c -> candidateFeatures(c, areaRates)).toArray(double[][]::new))).mapToDouble(p -> p[1]).toArray();
        List<Integer> order = IntStream.range(0, candidates.size()).boxed().sorted(Comparator.comparingDouble((Integer i) -> scores[i]).reversed()).toList();
        return order.stream().map(candidates::get).toList();
    }
}

