    messages: [
      { role: "system", content: "Rate the candidate's fit for the job on skills and experience only." },
      { role: "user", content: "JOB:\n" + jobDescription + "\n\nRESUME:\n" + resumeText },
    ],
    response_format: zodResponseFormat(FitScore, "fit_score"),
  });
  return completion.choices[0].message.parsed!;
}

