import com.openai.client.OpenAIClient;
import com.openai.client.okhttp.OpenAIOkHttpClient;
import com.openai.models.ChatModel;
import com.openai.models.chat.completions.ChatCompletionCreateParams;
import com.openai.models.chat.completions.StructuredChatCompletionCreateParams;
import io.swagger.v3.oas.annotations.media.Schema;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;

public class Agent {

    private static final OpenAIClient client = OpenAIOkHttpClient.fromEnv();

    public static class FitScore {
        @Schema(minimum = "0", maximum = "100")
        public int score;
        public String rationale;
    }

    public record Candidate(String id, String resumeText) {}

    public static FitScore scoreCandidate(String jobDescription, String resumeText) {
        StructuredChatCompletionCreateParams<FitScore> params = ChatCompletionCreateParams.builder()
                .model(ChatModel.GPT_4O_MINI)
                .addSystemMessage("Rate the candidate's fit for the job on skills and experience only.")
                .addUserMessage("JOB:\n" + jobDescription + "\n\nRESUME:\n" + resumeText)
                .responseFormat(FitScore.class)
                .build();
        return client.chat().completions().create(params).choices().get(0).message().content().orElseThrow();
    }

    public static List<Candidate> rankCandidates(String jobDescription, List<Candidate> candidates) {
        List<Map.Entry<Integer, Candidate>> scored = new ArrayList<>(candidates.stream().map(c -> Map.entry(scoreCandidate(jobDescription, c.resumeText()).score, c)).toList());
        scored.sort(Map.Entry.<Integer, Candidate>comparingByKey().reversed());
        return scored.stream().map(Map.Entry::getValue).toList();
    }
}

