import sqlite3
from datetime import datetime, timezone
from openai import OpenAI

client = OpenAI()
db = sqlite3.connect("app.db")

def record_consent(user_id: str, purpose: str, granted: bool) -> None:
    db.execute(
        "INSERT INTO consent_records (user_id, purpose, granted, recorded_at) VALUES (?, ?, ?, ?)",
        (user_id, purpose, int(granted), datetime.now(timezone.utc).isoformat()),
    )
    db.commit()

def withdraw_consent(user_id: str, purpose: str) -> None:
    record_consent(user_id, purpose, False)

def has_consent(user_id: str, purpose: str) -> bool:
    row = db.execute(
        "SELECT granted FROM consent_records WHERE user_id = ? AND purpose = ? ORDER BY recorded_at DESC LIMIT 1",
        (user_id, purpose),
    ).fetchone()
    return bool(row and row[0])

def personalize_reply(user_id: str, message: str) -> str:
    if not has_consent(user_id, "ai_personalization"):
        raise PermissionError("User has not consented to AI personalization")
    resp = client.chat.completions.create(model="gpt-4o-mini", messages=[{"role": "user", "content": message}])
