import com.openai.client.OpenAIClient;
import com.openai.client.okhttp.OpenAIOkHttpClient;
import com.openai.models.ChatModel;
import com.openai.models.chat.completions.ChatCompletion;
import com.openai.models.chat.completions.ChatCompletionCreateParams;
import com.fasterxml.jackson.core.JsonProcessingException;
import com.fasterxml.jackson.databind.ObjectMapper;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

public class Service {

    private static final OpenAIClient client = OpenAIOkHttpClient.fromEnv();
    private static final ObjectMapper mapper = new ObjectMapper();

    // Only these ticket fields are needed to categorise an issue. Contact details,
    // account numbers and addresses never leave our system.
    private static final List<String> ALLOWED_FIELDS = List.of("product", "subject", "description", "planTier");

    public static Map<String, Object> minimizeTicket(Map<String, Object> ticket) {
        Map<String, Object> minimized = new LinkedHashMap<>();
        for (String field : ALLOWED_FIELDS) if (ticket.containsKey(field)) minimized.put(field, ticket.get(field));
        return minimized;
    }

    public static String categorizeTicket(Map<String, Object> ticket) throws JsonProcessingException {
        Map<String, Object> payload = minimizeTicket(ticket);
        ChatCompletion resp = client.chat().completions().create(ChatCompletionCreateParams.builder()
                .model(ChatModel.GPT_4O_MINI)
                .addSystemMessage("Classify the support ticket as billing, bug, how-to or other.")
                .addUserMessage(mapper.writeValueAsString(payload))
                .build());
        return resp.choices().get(0).message().content().orElse("").trim();
    }
}

