import io.pinecone.clients.Index;
import io.pinecone.clients.Pinecone;
import org.springframework.http.HttpStatus;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.transaction.support.TransactionTemplate;
import org.springframework.web.bind.annotation.DeleteMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.ResponseStatus;
import org.springframework.web.bind.annotation.RestController;

@RestController
public class Service {

    private final JdbcTemplate jdbc;
    private final TransactionTemplate tx;
    private final Index memoryIndex = new Pinecone.Builder(System.getenv("PINECONE_API_KEY")).build().getIndexConnection("chat-memory");

    public Service(JdbcTemplate jdbc, TransactionTemplate tx) {
        this.jdbc = jdbc;
        this.tx = tx;
    }

    public void deleteUserData(String userId) {
        tx.executeWithoutResult(status -> {
            jdbc.update("DELETE FROM chat_messages WHERE user_id = ?", userId);
            jdbc.update("DELETE FROM user_preferences WHERE user_id = ?", userId);
            jdbc.update("DELETE FROM users WHERE id = ?", userId);
            jdbc.update("INSERT INTO erasure_requests (completed_at) VALUES (now())");
        });
        // Conversation embeddings live in a per-user namespace
        memoryIndex.deleteAll("user-" + userId);
    }

    @DeleteMapping("/users/{userId}/data")
    @ResponseStatus(HttpStatus.NO_CONTENT)
    public void eraseUser(@PathVariable String userId) {
        deleteUserData(userId);
    }
}

