import com.google.protobuf.Struct;
import com.google.protobuf.Value;
import io.pinecone.clients.Index;
import io.pinecone.clients.Pinecone;
import java.util.List;
import java.util.UUID;
import org.springframework.http.HttpStatus;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.ResponseStatus;
import org.springframework.web.bind.annotation.RestController;

@RestController
public class Service {

    private final JdbcTemplate jdbc;
    private final Index memoryIndex = new Pinecone.Builder(System.getenv("PINECONE_API_KEY")).build().getIndexConnection("chat-memory");

    public Service(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    public void saveMessage(String userId, String role, String content, List<Float> embedding) {
        jdbc.update(
                "INSERT INTO chat_messages (user_id, role, content) VALUES (?, ?, ?)",
                userId, role, content);
        Struct metadata = Struct.newBuilder().putFields("text", Value.newBuilder().setStringValue(content).build()).build();
        memoryIndex.upsert(UUID.randomUUID().toString(), embedding, null, null, metadata, "user-" + userId);
    }

    @PostMapping("/users/{userId}/deactivate")
    @ResponseStatus(HttpStatus.NO_CONTENT)
    public void deactivateAccount(@PathVariable String userId) {
        jdbc.update("UPDATE users SET active = false WHERE id = ?", userId);
    }
}

