const RETENTION_PERIOD_DAYS = 30;
const pool = new pg.Pool({ connectionString: process.env.DATABASE_URL });

export async function saveTranscript(userId: string, transcript: string): Promise<void> {
  await pool.query(
    "INSERT INTO call_transcripts (user_id, body, created_at) VALUES ($1, $2, now())",
    [userId, transcript],
  );
}

export async function purgeExpiredTranscripts(): Promise<number> {
  const cutoff = new Date(Date.now() - RETENTION_PERIOD_DAYS * 24 * 60 * 60 * 1000);
  const result = await pool.query("DELETE FROM call_transcripts WHERE created_at < $1", [cutoff]);
  return result.rowCount ?? 0;
}

cron.schedule("0 3 * * *", () => {
  void purgeExpiredTranscripts();
}, { timezone: "UTC" });

