import java.time.Duration;
import java.time.OffsetDateTime;
import java.time.ZoneOffset;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.scheduling.annotation.EnableScheduling;
import org.springframework.scheduling.annotation.Scheduled;
import org.springframework.stereotype.Component;

@Component
@EnableScheduling
public class Service {

    private static final Duration RETENTION_PERIOD = Duration.ofDays(30);
    private final JdbcTemplate jdbc;

    public Service(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    public void saveTranscript(String userId, String transcript) {
        jdbc.update(
                "INSERT INTO call_transcripts (user_id, body, created_at) VALUES (?, ?, now())",
                userId, transcript);
    }

    @Scheduled(cron = "0 0 3 * * *", zone = "UTC")
    public int purgeExpiredTranscripts() {
        OffsetDateTime cutoff = OffsetDateTime.now(ZoneOffset.UTC).minus(RETENTION_PERIOD);
        return jdbc.update("DELETE FROM call_transcripts WHERE created_at < ?", cutoff);
    }
}

