import com.openai.azure.AzureOpenAIServiceVersion;
import com.openai.azure.credential.AzureApiKeyCredential;
import com.openai.client.OpenAIClient;
import com.openai.client.okhttp.OpenAIOkHttpClient;
import com.openai.models.ChatModel;
import com.openai.models.chat.completions.ChatCompletion;
import com.openai.models.chat.completions.ChatCompletionCreateParams;
import java.util.Set;
import software.amazon.awssdk.core.sync.RequestBody;
import software.amazon.awssdk.regions.Region;
import software.amazon.awssdk.services.s3.S3Client;
import software.amazon.awssdk.services.s3.model.PutObjectRequest;

public class Service {

    // Claim files contain EU personal data and must be processed and stored in the EEA only.
    private static final Set<String> ALLOWED_REGIONS = Set.of("swedencentral", "westeurope", "francecentral");
    private static final String REGION = System.getenv("AZURE_OPENAI_REGION");
    static {
        if (!ALLOWED_REGIONS.contains(REGION)) {
            throw new IllegalStateException("Region %s is outside the EU; refusing to start".formatted(REGION));
        }
    }

    private static final OpenAIClient client = OpenAIOkHttpClient.builder()
            .baseUrl("https://claims-%s.openai.azure.com".formatted(REGION))
            .credential(AzureApiKeyCredential.create(System.getenv("AZURE_OPENAI_API_KEY")))
            .azureServiceVersion(AzureOpenAIServiceVersion.fromString("2024-06-01"))
            .build();
    private static final S3Client s3 = S3Client.builder().region(Region.EU_CENTRAL_1).build();

    public static String summarizeClaim(String claimId, String claimText) {
        ChatCompletion resp = client.chat().completions().create(
                ChatCompletionCreateParams.builder().model(ChatModel.GPT_4O).addUserMessage("Summarize this insurance claim:\n" + claimText).build());
        String summary = resp.choices().get(0).message().content().orElse("");
        s3.putObject(PutObjectRequest.builder().bucket("claims-summaries-eu").key(claimId + ".txt").build(), RequestBody.fromString(summary));
        return summary;
    }
}

