    private static final Map<String, Dpia> DPIA_REGISTER = Map.of(
            "credit_limit_scoring", new Dpia("DPIA-2026-014", LocalDate.of(2026, 3, 2),
                                             LocalDate.of(2027, 3, 2), "dpo@example.eu"));

