        Dpia dpia = DPIA_REGISTER.get(operation);
        if (dpia == null) {
            throw new SecurityException("No DPIA on record for " + operation);
        }
        if (dpia.reviewDue().isBefore(LocalDate.now())) {
            throw new SecurityException("DPIA %s for %s is overdue for review".formatted(dpia.dpiaId(), operation));
        }
        return dpia;
    }

    public static String scoreCreditLimit(String applicantSummary) {
        Dpia dpia = requireDpia("credit_limit_scoring");
        log.info("credit_limit_scoring running under {}", dpia.dpiaId());
        ChatCompletion resp = client.chat().completions().create(
                ChatCompletionCreateParams.builder().model(ChatModel.GPT_4O).addUserMessage("Suggest a credit limit band (A-E) for:\n" + applicantSummary).build());
        return resp.choices().get(0).message().content().orElse("").trim();
    }
}

