                    List.of("contact details", "message content"), List.of("OpenAI (processor)"), "90 days"));

    public static Map<String, Map<String, Object>> exportRegister() {
        return PROCESSING_REGISTER.entrySet().stream().collect(Collectors.toMap(Map.Entry::getKey, e -> mapper.convertValue(e.getValue(), new TypeReference<Map<String, Object>>() {})));
    }

    public static String triageEmail(String body) {
        log.info("processing activity=support_triage purpose={}", PROCESSING_REGISTER.get("support_triage").purpose());
