import { randomUUID } from "node:crypto";

const AUTHORITY_NOTIFICATION_DEADLINE_MS = 72 * 60 * 60 * 1000;
const BULK_EXPORT_THRESHOLD = 5000;
const openIncidents = new Map<string, Record<string, unknown>>();

const postJson = (url: string, body: unknown) => fetch(url, { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify(body) });

export async function openBreachIncident(description: string, recordsAffected: number) {
  const detectedAt = new Date();
  const incident = { id: randomUUID(), description, recordsAffected, detectedAt: detectedAt.toISOString(),
    notifyAuthorityBy: new Date(detectedAt.getTime() + AUTHORITY_NOTIFICATION_DEADLINE_MS).toISOString() };
  openIncidents.set(incident.id, incident);
  await postJson(process.env.DPO_ALERT_WEBHOOK!, incident);
  return incident;
}

export async function notifySupervisoryAuthority(incidentId: string): Promise<void> {
  const incident = openIncidents.get(incidentId);
  const res = await postJson(process.env.SUPERVISORY_AUTHORITY_ENDPOINT!, incident);
