import com.fasterxml.jackson.databind.ObjectMapper;
import java.io.IOException;
import java.net.URI;
import java.net.http.HttpClient;
import java.net.http.HttpRequest;
import java.net.http.HttpResponse;
import java.time.Duration;
import java.time.Instant;
import java.util.Map;
import java.util.UUID;
import java.util.concurrent.ConcurrentHashMap;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

public class Service {

    private static final Logger log = LoggerFactory.getLogger("security");
    private static final Duration AUTHORITY_NOTIFICATION_DEADLINE = Duration.ofHours(72);
    private static final int BULK_EXPORT_THRESHOLD = 5_000;
    private static final Map<String, Incident> openIncidents = new ConcurrentHashMap<>();
    private static final HttpClient http = HttpClient.newHttpClient();
    private static final ObjectMapper mapper = new ObjectMapper();

    public record Incident(String id, String description, int recordsAffected, String detectedAt, String notifyAuthorityBy) {}

    private static HttpResponse<String> postJson(String url, Object body) throws IOException, InterruptedException {
        HttpRequest request = HttpRequest.newBuilder(URI.create(url)).timeout(Duration.ofSeconds(10)).header("Content-Type", "application/json")
                .POST(HttpRequest.BodyPublishers.ofString(mapper.writeValueAsString(body))).build();
        return http.send(request, HttpResponse.BodyHandlers.ofString());
    }

    public static Incident openBreachIncident(String description, int recordsAffected) throws IOException, InterruptedException {
        Instant detectedAt = Instant.now();
        Incident incident = new Incident(UUID.randomUUID().toString(), description, recordsAffected,
                detectedAt.toString(),
                detectedAt.plus(AUTHORITY_NOTIFICATION_DEADLINE).toString());
        openIncidents.put(incident.id(), incident);
        postJson(System.getenv("DPO_ALERT_WEBHOOK"), incident);
        return incident;
    }

    public static void notifySupervisoryAuthority(String incidentId) throws IOException, InterruptedException {
        Incident incident = openIncidents.get(incidentId);
        HttpResponse<String> res = postJson(System.getenv("SUPERVISORY_AUTHORITY_ENDPOINT"), incident);
        if (res.statusCode() >= 400) throw new IOException("Authority notification failed: " + res.statusCode());
        openIncidents.remove(incidentId);
        log.info("breach {} reported to authority (deadline {})", incidentId, incident.notifyAuthorityBy());
    }

    public static void onCustomerExport(String apiKeyId, int rows) throws IOException, InterruptedException {
        if (rows > BULK_EXPORT_THRESHOLD) {
            Incident incident = openBreachIncident("Bulk export of %d customer rows by key %s".formatted(rows, apiKeyId), rows);
            log.warn("possible personal data breach {}", incident.id());
        }
    }
}

