import com.openai.models.chat.completions.ChatCompletion;
import com.openai.models.chat.completions.ChatCompletionCreateParams;
import com.fasterxml.jackson.core.JsonProcessingException;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.openai.models.ResponseFormatJsonObject;
import java.time.Instant;
import java.util.List;
import java.util.Map;
import java.util.UUID;
import java.util.concurrent.ConcurrentHashMap;

public class Service {

    private static final OpenAIClient client = OpenAIOkHttpClient.fromEnv();
    private static final ObjectMapper mapper = new ObjectMapper();
    private static final String MODEL = "gpt-4o-2024-08-06";
    private static final Map<String, LoanOutcome> decisions = new ConcurrentHashMap<>();

    public record ModelResult(String decision, List<String> principalReasons, List<String> dataUsed) {}

    public record LoanOutcome(String id, String applicantId, String model, String decidedAt,
                                 String decision, List<String> principalReasons, List<String> dataUsed) {}

    public static LoanOutcome decideLoan(Map<String, Object> applicant) throws JsonProcessingException {
        ChatCompletion resp = client.chat().completions().create(ChatCompletionCreateParams.builder().model(MODEL).responseFormat(ResponseFormatJsonObject.builder().build())
                .addSystemMessage("Return JSON with decision (approve|deny), principalReasons "
                        + "(list of strings) and dataUsed (list of applicant fields you relied on).")
                .addUserMessage(mapper.writeValueAsString(applicant))
                .build());
        ModelResult result = mapper.readValue(resp.choices().get(0).message().content().orElseThrow(), ModelResult.class);
        LoanOutcome record = new LoanOutcome(UUID.randomUUID().toString(), (String) applicant.get("id"), MODEL,
                Instant.now().toString(), result.decision(), result.principalReasons(), result.dataUsed());
        decisions.put(record.id(), record);
        return record;
    }

    public static String explainDecision(String decisionId) {
        LoanOutcome record = decisions.get(decisionId);
        if (!"deny".equals(record.decision())) {
            return "Your application was approved.";
        }
        return "Your application was denied. Principal reasons: %s. ".formatted(String.join("; ", record.principalReasons()))
                + "Information we used: %s.".formatted(String.join(", ", record.dataUsed()));
    }
}

