import { randomUUID } from "node:crypto";

type Decision = { inputs: Record<string, unknown>; decision: string; status: string };
type ReviewTicket = {
  id: string; decisionId: string; statement: string; reviewer: string | null; requestedAt: string; outcome?: string; notes?: string;
};

export const decisions = new Map<string, Decision>(); // written by the underwriting model
const dataCorrections: Record<string, unknown>[] = [];
const humanReviewQueue: ReviewTicket[] = [];

export function submitCorrection(decisionId: string, field: string, correctedValue: unknown, evidenceUrl?: string): void {
  const decision = decisions.get(decisionId)!;
  dataCorrections.push({ decisionId, field, oldValue: decision.inputs[field], newValue: correctedValue, evidenceUrl, submittedAt: new Date().toISOString() });
  decision.inputs[field] = correctedValue;
  decision.status = "pendingReevaluation";
}

export function requestHumanReview(decisionId: string, consumerStatement: string): ReviewTicket {
  const ticket: ReviewTicket = { id: randomUUID(), decisionId, statement: consumerStatement, reviewer: null, requestedAt: new Date().toISOString() };
  humanReviewQueue.push(ticket);
  decisions.get(decisionId)!.status = "pendingHumanReview";
  return ticket;
}

export function completeHumanReview(ticketId: string, reviewer: string, outcome: string, notes: string): void {
  const ticket = humanReviewQueue.find((t) => t.id === ticketId)!;
  Object.assign(ticket, { reviewer, outcome, notes });
  Object.assign(decisions.get(ticket.decisionId)!, { decision: outcome, status: "humanReviewed" });
}

