import java.time.Instant;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.UUID;
import java.util.concurrent.ConcurrentHashMap;

public class Service {

    public static class Decision {
        public Map<String, Object> inputs;
        public String decision;
        public String status;
    }

    public record DataCorrection(String decisionId, String field, Object oldValue, Object newValue, String evidenceUrl, String submittedAt) {}

    public static class ReviewTicket {
        public final String id = UUID.randomUUID().toString();
        public final String decisionId;
        public final String statement;
        public final String requestedAt = Instant.now().toString();
        public String reviewer;
        public String outcome;
        public String notes;

        ReviewTicket(String decisionId, String statement) {
            this.decisionId = decisionId;
            this.statement = statement;
        }
    }

    public static final Map<String, Decision> decisions = new ConcurrentHashMap<>(); // written by the underwriting model
    private static final List<DataCorrection> dataCorrections = new ArrayList<>();
    private static final List<ReviewTicket> humanReviewQueue = new ArrayList<>();

    public static void submitCorrection(String decisionId, String field, Object correctedValue) {
        submitCorrection(decisionId, field, correctedValue, null);
    }

    public static void submitCorrection(String decisionId, String field, Object correctedValue, String evidenceUrl) {
        Decision decision = decisions.get(decisionId);
        dataCorrections.add(new DataCorrection(
                decisionId, field, decision.inputs.get(field),
                correctedValue, evidenceUrl,
                Instant.now().toString()));
        decision.inputs.put(field, correctedValue);
        decision.status = "pending_reevaluation";
    }

    public static ReviewTicket requestHumanReview(String decisionId, String consumerStatement) {
        ReviewTicket ticket = new ReviewTicket(decisionId, consumerStatement);
        humanReviewQueue.add(ticket);
        decisions.get(decisionId).status = "pending_human_review";
        return ticket;
    }

    public static void completeHumanReview(String ticketId, String reviewer, String outcome, String notes) {
        ReviewTicket ticket = humanReviewQueue.stream().filter(t -> t.id.equals(ticketId)).findFirst().orElseThrow();
        ticket.reviewer = reviewer; ticket.outcome = outcome; ticket.notes = notes;
        Decision decision = decisions.get(ticket.decisionId); decision.decision = outcome; decision.status = "human_reviewed";
    }
}

