import com.fasterxml.jackson.core.JsonProcessingException;
import com.fasterxml.jackson.databind.ObjectMapper;
import java.time.Duration;
import java.time.Instant;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.stream.Collectors;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.datasource.SingleConnectionDataSource;

public class Service {

    private static final JdbcTemplate db = new JdbcTemplate(new SingleConnectionDataSource("jdbc:sqlite:hiring.db", true));
    private static final ObjectMapper mapper = new ObjectMapper();
    private static final Duration ADS_RECORD_RETENTION = Duration.ofDays(4 * 365); // keep ADS records for at least four years
    private static final double IMPACT_RATIO_THRESHOLD = 0.8; // four-fifths rule

    public record Outcome(String group, boolean advanced) {}

    public record GroupResult(double selectionRate, double impactRatio, boolean flagged) {}

    public static void storeScreeningRecord(String candidateId, Map<String, Object> inputs, double score, boolean advanced) throws JsonProcessingException {
        Instant now = Instant.now();
        db.update(
                "INSERT INTO ads_records (candidate_id, inputs, score, advanced, created_at, retain_until) VALUES (?, ?, ?, ?, ?, ?)",
                candidateId, mapper.writeValueAsString(inputs), score, advanced ? 1 : 0, now.toString(), now.plus(ADS_RECORD_RETENTION).toString());
    }

    public static Map<String, GroupResult> runAdverseImpactTest(List<Outcome> outcomes) throws JsonProcessingException {
        Map<String, Integer> totals = new HashMap<>(), selected = new HashMap<>();
        for (Outcome outcome : outcomes) {
            totals.merge(outcome.group(), 1, Integer::sum);
            selected.merge(outcome.group(), outcome.advanced() ? 1 : 0, Integer::sum);
        }
        Map<String, Double> rates = totals.keySet().stream().collect(Collectors.toMap(group -> group, group -> (double) selected.get(group) / totals.get(group)));
        double best = rates.values().stream().mapToDouble(Double::doubleValue).filter(rate -> rate > 0).max().orElse(1.0);
        Map<String, GroupResult> report = rates.entrySet().stream().collect(Collectors.toMap(Map.Entry::getKey,
                e -> new GroupResult(e.getValue(), e.getValue() / best, e.getValue() / best < IMPACT_RATIO_THRESHOLD)));
        db.update("INSERT INTO bias_audits (run_at, report) VALUES (?, ?)",
                Instant.now().toString(), mapper.writeValueAsString(report));
        return report;
    }
}

