import com.openai.client.OpenAIClient;
import com.openai.client.okhttp.OpenAIOkHttpClient;
import com.openai.models.ChatModel;
import com.openai.models.chat.completions.ChatCompletion;
import com.openai.models.chat.completions.ChatCompletionCreateParams;
import java.util.Comparator;
import java.util.List;

public class Service {

    private static final OpenAIClient client = OpenAIOkHttpClient.fromEnv();

    public record Candidate(String id, String resumeText) {}

    public record ScoredCandidate(Candidate candidate, double score) {}

    public static double scoreCandidate(String resumeText, String jobDescription) {
        ChatCompletion resp = client.chat().completions().create(ChatCompletionCreateParams.builder()
                .model(ChatModel.GPT_4O_MINI)
                .addSystemMessage("Score how well the resume fits the job from 0 to 100. Reply with the number only.")
                .addUserMessage("JOB:\n%s\n\nRESUME:\n%s".formatted(jobDescription, resumeText))
                .build());
        return Double.parseDouble(resp.choices().get(0).message().content().orElseThrow().trim());
    }

    public static List<ScoredCandidate> shortlist(List<Candidate> candidates, String jobDescription) {
        return shortlist(candidates, jobDescription, 10);
    }

    public static List<ScoredCandidate> shortlist(List<Candidate> candidates, String jobDescription, int topN) {
        List<ScoredCandidate> scored = candidates.stream().map(c -> new ScoredCandidate(c, scoreCandidate(c.resumeText(), jobDescription))).toList();
        return scored.stream().sorted(Comparator.comparingDouble(ScoredCandidate::score).reversed()).limit(topN).toList();
    }
}

