import com.openai.client.OpenAIClient;
import com.openai.client.okhttp.OpenAIOkHttpClient;
import com.openai.models.images.ImageGenerateParams;
import com.openai.models.images.ImageModel;
import com.openai.models.images.ImagesResponse;
import java.awt.image.BufferedImage;
import java.io.ByteArrayInputStream;
import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.time.Instant;
import java.util.Base64;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.UUID;
import javax.imageio.ImageIO;
import org.apache.commons.imaging.formats.png.AbstractPngText;
import org.apache.commons.imaging.formats.png.PngImageParser;
import org.apache.commons.imaging.formats.png.PngImagingParameters;

public class Service {

    private static final OpenAIClient client = OpenAIOkHttpClient.fromEnv();
    private static final String PROVIDER = "Example Media Inc.";
    private static final String SYSTEM_NAME = "PosterGen 2.1 (gpt-image-1)";
    private static final String DESCRIPTION = "Description", SOFTWARE = "Software"; // PNG tEXt keywords

    public record Poster(byte[] image, Map<String, Object> metadata) {}

    public static Poster generatePoster(String prompt) throws IOException {
        ImagesResponse result = client.images().generate(ImageGenerateParams.builder().model(ImageModel.GPT_IMAGE_1).prompt(prompt).size(ImageGenerateParams.Size._1024X1024).build());
        BufferedImage image = ImageIO.read(new ByteArrayInputStream(Base64.getDecoder().decode(result.data().orElseThrow().get(0).b64Json().orElseThrow())));
        Map<String, Object> provenance = Map.of("aiGenerated", true, "provider", PROVIDER, "system", SYSTEM_NAME,
                "contentId", UUID.randomUUID().toString(), "createdAt", Instant.now().toString());
        PngImagingParameters params = new PngImagingParameters();
        params.setTextChunks(List.of(
                new AbstractPngText.Text(DESCRIPTION, "AI-generated content. Provider: %s. ID: %s".formatted(PROVIDER, provenance.get("contentId"))),
                new AbstractPngText.Text(SOFTWARE, SYSTEM_NAME)));
        ByteArrayOutputStream out = new ByteArrayOutputStream();
        new PngImageParser().writeImage(image, out, params);
        Map<String, Object> metadata = new HashMap<>(provenance);
        metadata.put("label", "Made with AI");
        return new Poster(out.toByteArray(), metadata);
    }
}

