  "application instead, and you may ask how the technology reached its decision.";
export type Application = { consumerId: string; summary: string; admtNoticeGivenAt?: string };
const optedOut = new Set<string>();
const humanReviewQueue: Application[] = [];

export function givePreUseNotice(application: Application): string {
  application.admtNoticeGivenAt = new Date().toISOString();
  return PRE_USE_NOTICE;
}

