  if (!application.admtNoticeGivenAt) throw new Error("Pre-use notice must be given before using ADMT");
  if (optedOut.has(application.consumerId)) {
    humanReviewQueue.push(application);
    return "PENDING_HUMAN_REVIEW";
  }
  const resp = await client.chat.completions.create({ model: "gpt-4o", messages: [
    { role: "system", content: "Answer ACCEPT or REJECT for this tenant application." },
    { role: "user", content: application.summary },
  ] });
  return (resp.choices[0].message.content ?? "").trim();
}

