import com.openai.client.OpenAIClient;
import com.openai.client.okhttp.OpenAIOkHttpClient;
import com.openai.models.ChatModel;
import com.openai.models.chat.completions.ChatCompletion;
import com.openai.models.chat.completions.ChatCompletionCreateParams;
import java.time.Instant;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.concurrent.ConcurrentHashMap;

public class Service {

    private static final OpenAIClient client = OpenAIOkHttpClient.fromEnv();
    private static final String PRE_USE_NOTICE =
            "We use automated decision-making technology to evaluate rental applications. It considers your "
            + "income, rental history and credit report. You may opt out and have a person review your "
            + "application instead, and you may ask how the technology reached its decision.";
    private static final Set<String> optedOut = ConcurrentHashMap.newKeySet();
    private static final List<Map<String, String>> humanReviewQueue = new ArrayList<>();

    public static String givePreUseNotice(Map<String, String> application) {
        application.put("admtNoticeGivenAt", Instant.now().toString());
        return PRE_USE_NOTICE;
    }

    public static void optOutOfAdmt(String consumerId) {
        optedOut.add(consumerId);
    }

    public static String evaluateApplication(Map<String, String> application) {
        if (application.get("admtNoticeGivenAt") == null) {
            throw new IllegalStateException("Pre-use notice must be given before using ADMT");
        }
        if (optedOut.contains(application.get("consumerId"))) {
            humanReviewQueue.add(application);
            return "PENDING_HUMAN_REVIEW";
        }
        ChatCompletion resp = client.chat().completions().create(ChatCompletionCreateParams.builder().model(ChatModel.GPT_4O)
                .addSystemMessage("Answer ACCEPT or REJECT for this tenant application.")
                .addUserMessage(application.get("summary")).build());
        return resp.choices().get(0).message().content().orElse("").trim();
    }
}

