import com.fasterxml.jackson.core.JsonProcessingException;
import com.fasterxml.jackson.databind.ObjectMapper;
import java.util.Map;

public class Service {

    private static final OpenAIClient client = OpenAIOkHttpClient.fromEnv();
    private static final ObjectMapper mapper = new ObjectMapper();

    public static String evaluateApplication(Map<String, Object> application, Map<String, Object> creditReport) throws JsonProcessingException {
        ChatCompletion resp = client.chat().completions().create(ChatCompletionCreateParams.builder()
                .model(ChatModel.GPT_4O)
                .addSystemMessage("Answer ACCEPT or REJECT for this tenant application.")
                .addUserMessage(mapper.writeValueAsString(Map.of("application", application, "credit", creditReport)))
