}

const aiSystemInventory = new Map<string, AiSystem>([
  ["support-bot", { systemId: "support-bot", purpose: "Answer billing questions", owner: "cx-platform@example.com", provider: "OpenAI", model: "gpt-4o-mini", deployedOn: "2025-09-01", riskTier: "limited" }],
  ["claims-summarizer", { systemId: "claims-summarizer", purpose: "Summarize claim files for adjusters", owner: "claims-eng@example.com", provider: "OpenAI", model: "gpt-4o", deployedOn: "2026-01-15", riskTier: "high" }],
]);

