java.Service.java:
import com.openai.client.OpenAIClient;
import com.openai.client.okhttp.OpenAIOkHttpClient;
import com.openai.models.ChatModel;
import com.openai.models.chat.completions.ChatCompletion;
import com.openai.models.chat.completions.ChatCompletionCreateParams;
import com.fasterxml.jackson.core.type.TypeReference;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.SerializationFeature;
import com.fasterxml.jackson.datatype.jsr310.JavaTimeModule;
import com.openai.models.chat.completions.ChatCompletionMessageParam;
import java.time.LocalDate;
import java.util.List;
import java.util.Map;
import java.util.NoSuchElementException;
import java.util.stream.Collectors;
import java.util.stream.Stream;

public class Service {

    private static final OpenAIClient client = OpenAIOkHttpClient.fromEnv();
    private static final ObjectMapper mapper = new ObjectMapper().registerModule(new JavaTimeModule()).disable(SerializationFeature.WRITE_DATES_AS_TIMESTAMPS);

    public record AiSystem(
            String systemId,
            String purpose,
            String owner,
            String provider,
            String model,
            LocalDate deployedOn,
            String riskTier) {}

    private static final Map<String, AiSystem> AI_SYSTEM_INVENTORY = Stream.of(
            new AiSystem("support-bot", "Answer billing questions", "cx-platform@example.com", "OpenAI", "gpt-4o-mini", LocalDate.of(2025, 9, 1), "limited"),
            new AiSystem("claims-summarizer", "Summarize claim files for adjusters", "claims-eng@example.com", "OpenAI", "gpt-4o", LocalDate.of(2026, 1, 15), "high")
    ).collect(Collectors.toMap(AiSystem::systemId, s -> s));

    public static List<Map<String, Object>> exportInventory() {
        return AI_SYSTEM_INVENTORY.values().stream().map(s -> mapper.convertValue(s, new TypeReference<Map<String, Object>>() {})).toList();
    }

    public static String complete(String systemId, List<ChatCompletionMessageParam> messages) {
        AiSystem system = AI_SYSTEM_INVENTORY.get(systemId);
        if (system == null) {
            throw new NoSuchElementException("AI system '%s' is not in the inventory; register it before deploying".formatted(systemId));
        }
        ChatCompletion resp = client.chat().completions().create(ChatCompletionCreateParams.builder().model(system.model()).messages(messages).build());
        return resp.choices().get(0).message().content().orElse("");
    }
}

